import { createSlice, createAsyncThunk } from "@reduxjs/toolkit";
import API, { setAuthToken } from "../root/api";

export const login = createAsyncThunk(
  "auth/login",
  async ({ username, password }, { rejectWithValue }) => {
    try {
      const res = await API.post("/auth/login", { username, password });
      return res.data;
    } catch (err) {
      return rejectWithValue(err.response?.data || err.message);
    }
  },
);

export const register = createAsyncThunk(
  "auth/register",
  async ({ username, password, roles }, { rejectWithValue }) => {
    try {
      const res = await API.post("/auth/register", {
        username,
        password,
        roles,
      });
      return res.data;
    } catch (err) {
      return rejectWithValue(err.response?.data || err.message);
    }
  },
);

const authSlice = createSlice({
  name: "auth",
  initialState: {
    token: localStorage.getItem("token") || null,
    username: localStorage.getItem("username") || null,
    roles: JSON.parse(localStorage.getItem("roles")) || [],
    status: "idle",
    error: null,
  },
  reducers: {
    logout(state) {
      state.token = null;
      state.username = null;
      state.roles = [];
      localStorage.removeItem("token");
      localStorage.removeItem("username");
      localStorage.removeItem("roles");
      setAuthToken(null);
    },
    setToken(state, action) {
      state.token = action.payload;
      localStorage.setItem("token", action.payload);
      setAuthToken(action.payload);
    },
    // Add this to update roles from localStorage on app start
    loadFromStorage(state) {
      const storedRoles = localStorage.getItem("roles");
      if (storedRoles) {
        state.roles = JSON.parse(storedRoles);
      }
      const storedUsername = localStorage.getItem("username");
      if (storedUsername) {
        state.username = storedUsername;
      }
    },
  },
  extraReducers: (builder) => {
    builder
      .addCase(login.pending, (state) => {
        state.status = "loading";
        state.error = null;
      })
      .addCase(login.fulfilled, (state, action) => {
        state.status = "succeeded";
        state.token = action.payload.token;
        state.username = action.payload.username || action.payload.name;
        state.roles = action.payload.roles || [];
        state.error = null;

        // Store in localStorage
        localStorage.setItem("token", action.payload.token);
        if (action.payload.username) {
          localStorage.setItem("username", action.payload.username);
        }
        if (action.payload.roles) {
          localStorage.setItem("roles", JSON.stringify(action.payload.roles));
        }
        setAuthToken(action.payload.token);
      })
      .addCase(login.rejected, (state, action) => {
        state.status = "failed";
        state.error = action.payload;
      })
      .addCase(register.pending, (state) => {
        state.status = "loading";
        state.error = null;
      })
      .addCase(register.fulfilled, (state, action) => {
        state.status = "succeeded";
        state.token = action.payload.token;
        state.username = action.payload.username;
        state.roles = action.payload.roles || [];
        state.error = null;

        // Store in localStorage
        localStorage.setItem("token", action.payload.token);
        localStorage.setItem("username", action.payload.username);
        if (action.payload.roles) {
          localStorage.setItem("roles", JSON.stringify(action.payload.roles));
        }
        setAuthToken(action.payload.token);
      })
      .addCase(register.rejected, (state, action) => {
        state.status = "failed";
        state.error = action.payload;
      });
  },
});

export const { logout, setToken, loadFromStorage } = authSlice.actions;
export default authSlice.reducer;
